Rule.fixtext:
Run the following script to set mode, ownership, and group on the private SSH host key files: #!/usr/bin/env bash { a_output=(); a_output2=(); l_ssh_group_name="$(awk -F: '($1 ~ /^(ssh_keys|_?ssh)$/) {print $1}' /etc/group)" f_file_access_fix() { while IFS=: read -r l_file_mode l_file_owner l_file_group; do a_out2=() [ "$l_file_group" = "$l_ssh_group_name" ] && l_pmask="0137" || l_pmask="0177" l_maxperm="$( printf '%o' $(( 0777 & ~$l_pmask )) )" if [ $(( $l_file_mode & $l_pmask )) -gt 0 ]; then a_out2+=(" Mode: "$l_file_mode" should be mode: "$l_maxperm" or more restrictive" \ " updating to mode: \:$l_maxperm"") if [ "l_file_group" = "$l_ssh_group_name" ]; then chmod u-x,g-wx,o-rwx "$l_file" else chmod u-x,go-rwx "$l_file" fi fi if [ "$l_file_owner" != "root" ]; then a_out2+=(" Owned by: "$l_file_owner" should be owned by "root"" \ " Changing ownership to "root"") chown root "$l_file" fi if [[ ! "$l_file_group" =~ ($l_ssh_group_name|root) ]]; then [ -n "$l_ssh_group_name" ] && l_new_group="$l_ssh_group_name" || l_new_group="root" a_out2+=(" Owned by group "$l_file_group" should be group owned by: "$l_ssh_group_name" or "root"" \ " Changing group ownership to "$l_new_group"") chgrp "$l_new_group" "$l_file" fi if [ "${#a_out2[@]}" -gt "0" ]; then a_output2+=(" - File: "$l_file"" "${a_out2[@]}") else a_output+=(" - File: "$l_file"" \ "Correct: mode: "$l_file_mode", owner: "$l_file_owner", and group owner: "$l_file_group" configured") fi done < <(stat -Lc '%#a:%U:%G' "$l_file") } while IFS= read -r -d $'\0' l_file; do if ssh-keygen -lf &>/dev/null "$l_file"; then file "$l_file" | grep -Piq -- ' openssh\h+([^#
]+\h+)?private\h+key ' && f_file_access_fix fi done < <(find -L /etc/ssh -xdev -type f -print0 2>/dev/null) if [ "${#a_output2[@]}" -le "0" ]; then printf '%s
' "" " - No access changes required" "" else printf '%s
' "" " - Remediation results:" "${a_output2[@]}" "" fi }

check.check-content:
Run the following script to verify SSH private host key files are owned by the root user and either: • owned by the group root and mode 0600 or more restrictive - OR - • owned by the group designated to own openSSH private keys and mode 0640 or more restrictive #!/usr/bin/env bash { a_output=(); a_output2=() l_ssh_group_name="$(awk -F: '($1 ~ /^(ssh_keys|_?ssh)$/) {print $1}' /etc/group)" f_file_chk() { while IFS=: read -r l_file_mode l_file_owner l_file_group; do a_out2=() [ "$l_file_group" = "$l_ssh_group_name" ] && l_pmask="0137" || l_pmask="0177" l_maxperm="$( printf '%o' $(( 0777 & ~$l_pmask )) )" if [ $(( $l_file_mode & $l_pmask )) -gt 0 ]; then a_out2+=(" Mode: "$l_file_mode" should be mode: "$l_maxperm" or more restrictive") fi if [ "$l_file_owner" != "root" ]; then a_out2+=(" Owned by: "$l_file_owner" should be owned by "root"") fi if [[ ! "$l_file_group" =~ ($l_ssh_group_name|root) ]]; then a_out2+=(" Owned by group "$l_file_group" should be group owned by: "$l_ssh_group_name" or "root"") fi if [ "${#a_out2[@]}" -gt "0" ]; then a_output2+=(" - File: "$l_file"${a_out2[@]}") else a_output+=(" - File: "$l_file"" \ " Correct: mode: "$l_file_mode", owner: "$l_file_owner" and group owner: "$l_file_group" configured") fi done < <(stat -Lc '%#a:%U:%G' "$l_file") } while IFS= read -r -d $'\0' l_file; do if ssh-keygen -lf &>/dev/null "$l_file"; then file "$l_file" | grep -Piq -- ' openssh\h+([^#
]+\h+)?private\h+key ' && f_file_chk fi done < <(find -L /etc/ssh -xdev -type f -print0 2>/dev/null) if [ "${#a_output2[@]}" -le 0 ]; then printf '%s
' "" "- Audit Result:" " ** PASS **" "${a_output[@]}" "" else printf '%s
' "" "- Audit Result:" " ** FAIL **" " - Reason(s) for audit failure:" "${a_output2[@]}" [ "${#a_output[@]}" -gt 0 ] && printf '%s
' "" "- Correctly set:" "${a_output[@]}" "" fi }

Rule.fixtext:
Run the following script to set mode, ownership, and group on the public SSH host key files: #!/usr/bin/env bash { a_output=(); a_output2=() l_pmask="0133"; l_maxperm="$( printf '%o' $(( 0777 & ~$l_pmask )) )" f_file_access_fix() { while IFS=: read -r l_file_mode l_file_owner l_file_group; do a_out2=() [ $(( $l_file_mode & $l_pmask )) -gt 0 ] && \ a_out2+=(" Mode: "$l_file_mode" should be mode: "$l_maxperm" or more restrictive" \ " updating to mode: "$l_maxperm"") && chmod u-x,go-wx "$l_file" [ "$l_file_owner" != "root" ] && \ a_out2+=(" Owned by: "$l_file_owner" should be owned by "root"" \ " Changing ownership to "root"") && chown root "$l_file" [ "$l_file_group" != "root" ] && \ a_out2+=(" Owned by group "$l_file_group" should be group owned by: "root"" \ " Changing group ownership to "root"") && chgrp root "$l_file" if [ "${#a_out2[@]}" -gt "0" ]; then a_output2+=(" - File: "$l_file"" "${a_out2[@]}") else a_output+=(" - File: "$l_file"" \ " Correct: mode: "$l_file_mode", owner: "$l_file_owner", and group owner: "$l_file_group" configured") fi done < <(stat -Lc '%#a:%U:%G' "$l_file") } while IFS= read -r -d $'\0' l_file; do if ssh-keygen -lf &>/dev/null "$l_file"; then file "$l_file" | grep -Piq -- ' openssh\h+([^#
]+\h+)?public\h+key ' && f_file_access_fix fi done < <(find -L /etc/ssh -xdev -type f -print0 2>/dev/null) if [ "${#a_output2[@]}" -le "0" ]; then printf '%s
' "" " - No access changes required" "" else printf '%s
' " - Remediation results:" "${a_output2[@]}" "" fi }

check.check-content:
Run the following script to verify SSH public host key files are mode 0644 or more restrictive, owned by the root user, and owned by the root group: #!/usr/bin/env bash { a_output=(); a_output2=() l_pmask="0133"; l_maxperm="$( printf '%o' $(( 0777 & ~$l_pmask )) )" f_file_chk() { while IFS=: read -r l_file_mode l_file_owner l_file_group; do a_out2=() if [ $(( $l_file_mode & $l_pmask )) -gt 0 ]; then a_out2+=(" Mode: "$l_file_mode" should be mode: "$l_maxperm" or more restrictive") fi if [ "$l_file_owner" != "root" ]; then a_out2+=(" Owned by: "$l_file_owner" should be owned by: "root"") fi if [ "$l_file_group" != "root" ]; then a_out2+=(" Owned by group "$l_file_group" should be group owned by group: "root"") fi if [ "${#a_out2[@]}" -gt "0" ]; then a_output2+=(" - File: "$l_file"" "${a_out2[@]}") else a_output+=(" - File: "$l_file"" \ " Correct: mode: "$l_file_mode", owner: "$l_file_owner" and group owner: "$l_file_group" configured") fi done < <(stat -Lc '%#a:%U:%G' "$l_file") } while IFS= read -r -d $'\0' l_file; do if ssh-keygen -lf &>/dev/null "$l_file"; then file "$l_file" | grep -Piq -- ' openssh\h+([^#
]+\h+)?public\h+key ' && f_file_chk fi done < <(find -L /etc/ssh -xdev -type f -print0 2>/dev/null) if [ "${#a_output2[@]}" -le 0 ]; then [ "${#a_output[@]}" -le 0 ] && a_output+=(" - No openSSH public keys found") printf '%s
' "" "- Audit Result:" " ** PASS **" "${a_output[@]}" "" else printf '%s
' "" "- Audit Result:" " ** FAIL **" " - Reason(s) for audit failure:" "${a_output2[@]}" [ "${#a_output[@]}" -gt 0 ] && printf '%s
' "" "- Correctly set:" "${a_output[@]}" "" fi }

Verify password creation requirements conform to organization policy. Run the following command to verify the minimum password length is 14 or more characters: # grep -Pi '^\h*minlen ' /etc/security/pwquality.conf minlen = 14 Run one of the following commands to verify the required password complexity: # grep -Pi '^\h*minclass ' /etc/security/pwquality.conf minclass = 4 -OR- # grep -Pi '^\h*[duol]credit ' /etc/security/pwquality.conf dcredit = -1 ucredit = -1 lcredit = -1 ocredit = -1 Run the following commands to verify the files: /etc/pam.d/system-password and /etc/pam.d/system-auth include retry=3 on the password requisite pam_pwquality.so line: # grep -P '^\h*password\h+([^#
]+\h+)?pam_pwquality\.so\h+([^#
]+\h+)?(retry=[1- 3]) ' /etc/pam.d/system-password Example output: password requisite pam_pwquality.so retry=3 # grep -P '^\h*password\h+([^#
]+\h+)?pam_pwquality\.so\h+([^#
]+\h+)?(retry=[1- 3]) ' /etc/pam.d/system-auth Example output: password requisite pam_pwquality.so retry=3

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_uid; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate UID: \"$l_uid\" Users: \"$(awk -F: '($3 == n) {
print $1 }' n=$l_uid /etc/passwd | xargs)\""
fi
done < <(cut -f3 -d":" /etc/passwd | sort -n | uniq -c)
}

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
